function reachable(edges, start){
  // edges: [{src,dst}]. Return sorted array of nodes reachable from start (excl. start).
  let frontier = [{ node: start, path: [start] }];
  const found = new Set();
  let iter = 0;
  while (frontier.length){
    if (++iter > 1000) throw new Error('did not terminate');
    const next = [];
    for (const f of frontier){
      for (const e of edges){
        if (e.src === f.node){
          // guard meant to block revisiting a node already on this path
          if (!f.path.includes(f.node)){
            found.add(e.dst);
            next.push({ node: e.dst, path: f.path.concat(e.dst) });
          }
        }
      }
    }
    frontier = next;
  }
  return [...found].sort((a,b)=>a-b);
}

